p = 61
counts = {k: 0 for k in range(p)}

for a in range(1, p + 1):
    for b in range(1, p + 1):
        # a^2 + b^2 mod 61
        sum_sq = (a*a + b*b) % p
        counts[sum_sq] += 1

# Convert to a list/array for reporting, ordered by K
results = [counts[k] for k in range(p)]

print(results)

